import{_ as t,o as a,c as n,aj as i}from"./chunks/framework.C6uXqnaX.js";const f=JSON.parse('{"title":"Performance","description":"","frontmatter":{},"headers":[],"relativePath":"en/best-practices/performance.md","filePath":"en/best-practices/performance.md"}'),r={name:"en/best-practices/performance.md"};function o(s,e,l,d,c,p){return a(),n("div",null,e[0]||(e[0]=[i('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>Angular includes many optimizations out of the box, but as applications grow, you may need to fine-tune both how quickly your app loads and how responsive it feels during use. These guides cover the tools and techniques Angular provides to help you build fast applications.</p><h2 id="loading-performance" tabindex="-1">Loading performance <a class="header-anchor" href="#loading-performance" aria-label="Permalink to &quot;Loading performance&quot;">​</a></h2><p>Loading performance determines how quickly your application becomes visible and interactive. Slow loading directly impacts <a href="https://web.dev/vitals/" target="_blank" rel="noreferrer">Core Web Vitals</a> like Largest Contentful Paint (LCP) and Time to First Byte (TTFB).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Technique</th><th style="text-align:left;">What it does</th><th style="text-align:left;">When to use it</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/en/best-practices/performance/lazy-loaded-routes#lazily-loaded-components-and-routes">Lazy-loaded routes</a></td><td style="text-align:left;">Defers loading route components until navigation, reducing the initial bundle size</td><td style="text-align:left;">Applications with multiple routes where not all are needed on initial load</td></tr><tr><td style="text-align:left;"><a href="/en/best-practices/performance/defer">Deferred loading with <code>@defer</code></a></td><td style="text-align:left;">Splits components into separate bundles that load on demand</td><td style="text-align:left;">Components not visible on initial render, heavy third-party libraries, below-the-fold content</td></tr><tr><td style="text-align:left;"><a href="/en/guide/di/lazy-loading-services">Lazy loading services with <code>injectAsync</code></a></td><td style="text-align:left;">Splits rarely used services into separate chunks and loads them on demand</td><td style="text-align:left;">Services backed by large libraries or infrequently used features</td></tr><tr><td style="text-align:left;"><a href="/en/best-practices/performance/image-optimization">Image optimization</a></td><td style="text-align:left;">Prioritizes LCP images, lazy loads others, generates responsive <code>srcset</code> attributes</td><td style="text-align:left;">Any application that displays images</td></tr><tr><td style="text-align:left;"><a href="/en/best-practices/performance/ssr">Server-side rendering</a></td><td style="text-align:left;">Renders pages on the server for faster first paint and better SEO, with <a href="/en/guide/hydration">hydration</a> to restore interactivity and <a href="/en/guide/incremental-hydration">incremental hydration</a> to defer hydrating sections until needed</td><td style="text-align:left;">Content-heavy applications, pages that need search engine indexing</td></tr></tbody></table><h2 id="runtime-performance" tabindex="-1">Runtime performance <a class="header-anchor" href="#runtime-performance" aria-label="Permalink to &quot;Runtime performance&quot;">​</a></h2><p>Runtime performance determines how responsive your application feels after it loads. Angular&#39;s change detection system keeps the DOM in sync with your data, and optimizing how and when it runs is the primary lever for improving runtime performance.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Technique</th><th style="text-align:left;">What it does</th><th style="text-align:left;">When to use it</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/en/guide/zoneless">Zoneless change detection</a></td><td style="text-align:left;">Removes ZoneJS overhead and triggers change detection only when signals or events indicate a change</td><td style="text-align:left;">New applications (default in Angular v21+), or existing applications ready to migrate</td></tr><tr><td style="text-align:left;"><a href="/en/best-practices/slow-computations">Slow computations</a></td><td style="text-align:left;">Identifies and optimizes expensive template expressions and lifecycle hooks</td><td style="text-align:left;">Profiling reveals specific components causing slow change detection cycles</td></tr><tr><td style="text-align:left;"><a href="/en/best-practices/skipping-subtrees">Skipping component subtrees</a></td><td style="text-align:left;">Uses <code>OnPush</code> change detection to skip unchanged component trees</td><td style="text-align:left;">Applications that need finer control over change detection</td></tr><tr><td style="text-align:left;"><a href="/en/best-practices/zone-pollution">Zone pollution</a></td><td style="text-align:left;">Prevents unnecessary change detection caused by third-party libraries or timers</td><td style="text-align:left;">Zone-based applications where profiling reveals excessive change detection cycles</td></tr></tbody></table><h2 id="measuring-performance" tabindex="-1">Measuring performance <a class="header-anchor" href="#measuring-performance" aria-label="Permalink to &quot;Measuring performance&quot;">​</a></h2><p>Identifying what to optimize is just as important as knowing how to optimize it. Angular integrates with browser developer tools to help you find bottlenecks.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tool</th><th style="text-align:left;">What it does</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/en/best-practices/profiling-with-chrome-devtools">Chrome DevTools profiling</a></td><td style="text-align:left;">Records Angular-specific performance data alongside browser profiling, with color-coded flame charts that show component rendering, change detection cycles, and lifecycle hooks</td></tr><tr><td style="text-align:left;"><a href="/en/tools/devtools">Angular DevTools</a></td><td style="text-align:left;">A browser extension that provides a component tree inspector and a profiler for visualizing change detection cycles</td></tr></tbody></table><h2 id="what-to-optimize-first" tabindex="-1">What to optimize first <a class="header-anchor" href="#what-to-optimize-first" aria-label="Permalink to &quot;What to optimize first&quot;">​</a></h2><p>If you are unsure where to start, profile your application first using the <a href="/en/best-practices/profiling-with-chrome-devtools">Chrome DevTools Angular track</a> to identify specific bottlenecks.</p><p>As a general starting point:</p><ul><li><strong>Slow initial load</strong> — Use <a href="/en/best-practices/performance/defer"><code>@defer</code></a> to split large components out of the main bundle, <a href="/en/best-practices/performance/image-optimization"><code>NgOptimizedImage</code></a> to prioritize above-the-fold images, and <a href="/en/best-practices/performance/ssr">server-side rendering</a> to deliver content faster.</li><li><strong>Slow interactions after load</strong> — Check whether <a href="/en/guide/zoneless">zoneless change detection</a> is enabled, look for <a href="/en/best-practices/slow-computations">slow computations</a> in templates or lifecycle hooks, and consider <a href="/en/best-practices/skipping-subtrees"><code>OnPush</code></a> to reduce unnecessary change detection.</li></ul>',15)]))}const g=t(r,[["render",o]]);export{f as __pageData,g as default};
